import{_ as i,o as a,c as e,ag as r}from"./chunks/framework.IxO3mcwW.js";const d="/getbiji-docs/images/siri-01.png",q=JSON.parse('{"title":"Siri 唤起","description":"","frontmatter":{},"headers":[],"relativePath":"efficiency/siri.md","filePath":"efficiency/siri.md","lastUpdated":1773215704000}'),l={name:"efficiency/siri.md"};function o(s,t,h,n,u,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="siri-唤起" tabindex="-1">Siri 唤起 <a class="header-anchor" href="#siri-唤起" aria-label="Permalink to &quot;Siri 唤起&quot;">​</a></h1><blockquote><p>解放双手，语音启动</p></blockquote><p>通过 Siri 快捷指令，无需打开 App 即可快速启动 Get 笔记各项功能。</p><h2 id="添加方法" tabindex="-1">添加方法 <a class="header-anchor" href="#添加方法" aria-label="Permalink to &quot;添加方法&quot;">​</a></h2><ol><li><p>iOS用户打开Get笔记App</p></li><li><p>点击右上角头像，进入个人中心</p></li><li><p>找到【Siri、操作按钮等快捷指令】入口</p></li><li><p>点击&quot;+&quot;按钮，添加需要的快捷指令</p></li></ol><h2 id="支持的快捷指令" tabindex="-1">支持的快捷指令 <a class="header-anchor" href="#支持的快捷指令" aria-label="Permalink to &quot;支持的快捷指令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>触发语</th><th>说明</th></tr></thead><tbody><tr><td>🎙️ 语音笔记</td><td>&quot;开始录&quot;</td><td>快速启动语音笔记功能，解放双手</td></tr><tr><td>👥 会议录音笔记</td><td>&quot;去开会&quot;</td><td>快速启动线下会议录音笔记功能，开会更高效</td></tr><tr><td>🤖 AI 助手</td><td>&quot;问助手&quot;</td><td>任何问题，直接去问 AI 助手，获取全面回答</td></tr><tr><td>⌨️ 文本笔记</td><td>&quot;写笔记&quot;</td><td>一键进入笔记编辑界面，立即记录</td></tr><tr><td>🔍 笔记搜索</td><td>&quot;搜笔记&quot;</td><td>快速进入搜索页面，查找所需内容</td></tr></tbody></table><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><ul><li>🚗 开车途中突然有灵感，用语音笔记快速记录</li><li>🏃 运动时记录训练数据，避免手机操作</li><li>🧑‍🍳 烹饪时双手被占用，用语音查找食谱笔记</li><li>📝 会议中需要快速记录，一键启动文本笔记</li></ul><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ul><li>可以根据个人习惯自定义触发语句，让操作更自然</li><li>建议在安静环境下使用语音指令，提高识别准确率</li></ul><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+d+'" alt="Siri快捷指令" style="width:180px;border-radius:8px;"></div>',13)])])}const _=i(l,[["render",o]]);export{q as __pageData,_ as default};
